package vn.wedding.invitation.imports;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import java.util.regex.Pattern;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;
import vn.wedding.invitation.common.ApiErrors;
import vn.wedding.invitation.invitations.TokenService;
import static vn.wedding.invitation.access.AccessGate.number;

@Service
public class ImportService {
    private static final List<String> HEADERS=List.of("externalRef","displayName","salutation","groupName","eventCodes","maxPeople");
    private static final Pattern INTEGER=Pattern.compile("[1-9][0-9]{0,1}");
    private final JdbcTemplate db;
    private final TokenService tokens;
    public ImportService(JdbcTemplate db,TokenService tokens){this.db=db;this.tokens=tokens;}
    public record ParsedRow(int line,String externalRef,String displayName,String salutation,String groupName,String eventCodes,String maxPeople,boolean valid,String message){}
    public record Preview(UUID batchId,int totalRows,int validRows,int invalidRows,List<ParsedRow> rows){}
    public Preview preview(MultipartFile file,UUID key){
        ApiErrors.require(file!=null&&!file.isEmpty(),"Vui lòng chọn tệp CSV.");ApiErrors.require(file.getSize()<=2*1024*1024,"Tệp CSV không được lớn hơn 2 MB.");
        try {byte[] bytes=file.getBytes();String text=new String(bytes,StandardCharsets.UTF_8);if(text.startsWith("\uFEFF"))text=text.substring(1);List<List<String>> records=parse(text);ApiErrors.require(records.size()>=2,"Tệp CSV cần có dòng tiêu đề và ít nhất một dòng dữ liệu.");ApiErrors.require(records.size()<=2001,"Tệp CSV không được quá 2.000 dòng dữ liệu.");
            String hash=TokenService.hash(text);var existing=db.queryForList("SELECT id,status,payload_hash,total_rows,valid_rows FROM import_batches WHERE idempotency_key=?",key);if(!existing.isEmpty()){var row=existing.getFirst();ApiErrors.require(hash.equals(row.get("payload_hash")),"Mã yêu cầu đã được dùng cho nội dung CSV khác.");return loadPreview((UUID)row.get("id"));}
            ApiErrors.require(records.getFirst().equals(HEADERS),"Tiêu đề CSV phải đúng thứ tự: externalRef, displayName, salutation, groupName, eventCodes, maxPeople.");
            List<ParsedRow> rows=new ArrayList<>();for(int i=1;i<records.size();i++)rows.add(validate(i+1,records.get(i)));
            UUID batch=UUID.randomUUID();int valid=(int)rows.stream().filter(ParsedRow::valid).count();db.update("INSERT INTO import_batches(id,idempotency_key,payload_hash,status,total_rows,valid_rows) VALUES(?,?,?,'PREVIEW',?,?)",batch,key,hash,rows.size(),valid);for(ParsedRow r:rows)db.update("INSERT INTO import_rows(batch_id,line_number,external_ref,display_name,salutation,group_name,event_codes,max_people_text,valid,message) VALUES(?,?,?,?,?,?,?,?,?,?)",batch,r.line(),r.externalRef(),r.displayName(),r.salutation(),r.groupName(),r.eventCodes(),r.maxPeople(),r.valid(),r.message());return new Preview(batch,rows.size(),valid,rows.size()-valid,rows);
        } catch(IOException e){throw new IllegalArgumentException("Không thể đọc tệp CSV.");}
    }
    @Transactional public Map<String,Object> commit(UUID batchId,UUID key){var batch=db.queryForMap("SELECT * FROM import_batches WHERE id=? FOR UPDATE",batchId);ApiErrors.require(Objects.equals(batch.get("idempotency_key"),key),"Lô nhập không thuộc yêu cầu này.");if("COMMITTED".equals(batch.get("status")))return Map.of("batchId",batchId,"created",batch.get("valid_rows"),"status","COMMITTED");ApiErrors.require("PREVIEW".equals(batch.get("status")),"Lô nhập không còn ở trạng thái chờ xác nhận.");ApiErrors.require(number(batch,"valid_rows")>0&&number(batch,"valid_rows")==number(batch,"total_rows"),"Tệp còn dòng lỗi. Hãy sửa tệp và xem trước lại.");
        db.query("SELECT * FROM import_rows WHERE batch_id=? ORDER BY line_number",rs->{while(rs.next()){String external=rs.getString("external_ref");if(external!=null&&db.queryForObject("SELECT count(*) FROM invitations WHERE external_ref=?",Integer.class,external)>0)throw new IllegalArgumentException("Mã tham chiếu đã tồn tại: "+external);String[] codes=rs.getString("event_codes").split(";");String[] limits=rs.getString("max_people_text").split(";");if(limits.length!=1&&limits.length!=codes.length)throw new IllegalArgumentException("Số giới hạn người không khớp dòng "+rs.getInt("line_number"));UUID invitation=UUID.randomUUID(),eventFirst=null;String token=tokens.mint();db.update("INSERT INTO invitations(id,external_ref,display_name,group_name,salutation,token_hash,token_cipher) VALUES(?,?,?,?,?,?,?)",invitation,external,rs.getString("display_name"),rs.getString("group_name"),rs.getString("salutation"),TokenService.hash(token),tokens.encrypt(token,invitation));for(int i=0;i<codes.length;i++){var event=db.queryForList("SELECT id FROM events WHERE event_code=? AND state<>'CANCELLED'",codes[i].trim());if(event.isEmpty())throw new IllegalArgumentException("Mã buổi tiệc không tồn tại: "+codes[i]);int limit=Integer.parseInt(limits.length==1?limits[0].trim():limits[i].trim());db.update("INSERT INTO assignments(invitation_id,event_id,max_people) VALUES(?,?,?)",invitation,event.getFirst().get("id"),limit);eventFirst=(UUID)event.getFirst().get("id");} }return null;},batchId);db.update("UPDATE import_batches SET status='COMMITTED',committed_at=now() WHERE id=?",batchId);db.update("INSERT INTO audit(action,target) VALUES('GUEST_IMPORT',?)",batchId);return Map.of("batchId",batchId,"created",batch.get("valid_rows"),"status","COMMITTED");}
    public Preview loadPreview(UUID id){var b=db.queryForMap("SELECT * FROM import_batches WHERE id=?",id);List<ParsedRow> rows=db.query("SELECT * FROM import_rows WHERE batch_id=? ORDER BY line_number",(rs,n)->new ParsedRow(rs.getInt("line_number"),rs.getString("external_ref"),rs.getString("display_name"),rs.getString("salutation"),rs.getString("group_name"),rs.getString("event_codes"),rs.getString("max_people_text"),rs.getBoolean("valid"),rs.getString("message")),id);return new Preview(id,((Number)b.get("total_rows")).intValue(),((Number)b.get("valid_rows")).intValue(),rows.size()-((Number)b.get("valid_rows")).intValue(),rows);}
    private ParsedRow validate(int line,List<String> values){if(values.size()!=6)return new ParsedRow(line,"","","","","","",false,"Dòng phải có đúng 6 cột.");String external=clean(values.get(0)),name=clean(values.get(1)),salutation=clean(values.get(2)),group=clean(values.get(3)),codes=clean(values.get(4)),limits=clean(values.get(5));List<String> errors=new ArrayList<>();if(name.isBlank()||name.length()>200)errors.add("Tên người nhận bắt buộc và tối đa 200 ký tự.");if(salutation.length()>80)errors.add("Xưng hô tối đa 80 ký tự.");if(group.length()>100)errors.add("Nhãn nhóm tối đa 100 ký tự.");if(codes.isBlank())errors.add("Cần ít nhất một mã buổi tiệc.");String[] codeArray=codes.split(";");String[] limitArray=limits.split(";");if(limitArray.length!=1&&limitArray.length!=codeArray.length)errors.add("Số giới hạn người phải là một giá trị hoặc khớp số buổi.");for(String limit:limitArray)if(!INTEGER.matcher(limit.trim()).matches()||Integer.parseInt(limit.trim())>20)errors.add("Giới hạn người phải từ 1 đến 20.");for(String code:codeArray){String normalized=code.trim();if(!normalized.matches("[A-Za-z0-9_-]{2,40}"))errors.add("Mã buổi tiệc không hợp lệ: "+normalized);else if(db.queryForObject("SELECT count(*) FROM events WHERE event_code=? AND state<>'CANCELLED'",Integer.class,normalized)!=1)errors.add("Không tìm thấy buổi tiệc đang hoạt động với mã: "+normalized);}if(external.length()>120)errors.add("Mã tham chiếu tối đa 120 ký tự.");if(!external.isBlank()&&db.queryForObject("SELECT count(*) FROM invitations WHERE external_ref=?",Integer.class,external)>0)errors.add("Mã tham chiếu đã tồn tại: "+external);return new ParsedRow(line,external,name,salutation.isBlank()?"Kính mời":salutation,group,codes,limits,errors.isEmpty(),String.join(" ",errors));}
    private static String clean(String value){String s=value==null?"":value.strip();if(s.startsWith("=")||s.startsWith("+")||s.startsWith("-")||s.startsWith("@"))return "";return s;}
    public static List<List<String>> parse(String text){List<List<String>> out=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){row.add(cell.toString());cell.setLength(0);}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;row.add(cell.toString());cell.setLength(0);if(row.stream().anyMatch(v->!v.isBlank()))out.add(row);row=new ArrayList<>();}else cell.append(c);}if(quoted)throw new IllegalArgumentException("CSV có dấu ngoặc kép chưa đóng.");if(cell.length()>0||!row.isEmpty()){row.add(cell.toString());out.add(row);}return out;}
}